export function useGetPublicShare<TData = Awaited<ReturnType<typeof getPublicShare>>, TError = ErrorType<ErrorResponse>>(
 token: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getPublicShare>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetPublicShareQueryOptions(token,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







export const getCreateReportUrl = () => {




  return `/api/v1/reports`
}

/**
 * @summary Report a participant or R.O.O.M.
 */
export const createReport = async (reportRequest: ReportRequest, options?: RequestInit): Promise<ReportResult> => {

  return customFetch<ReportResult>(getCreateReportUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(reportRequest)
  }
);}





export const getCreateReportMutationOptions = <TError = ErrorType<UnauthorizedResponse | ValidationErrorResponse | FirebaseUnavailableResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createReport>>, TError,{data: BodyType<ReportRequest>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createReport>>, TError,{data: BodyType<ReportRequest>}, TContext> => {

const mutationKey = ['createReport'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createReport>>, {data: BodyType<ReportRequest>}> = (props) => {
          const {data} = props ?? {};

          return  createReport(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateReportMutationResult = NonNullable<Awaited<ReturnType<typeof createReport>>>
    export type CreateReportMutationBody = BodyType<ReportRequest>
    export type CreateReportMutationError = ErrorType<UnauthorizedResponse | ValidationErrorResponse | FirebaseUnavailableResponse>

    /**
 * @summary Report a participant or R.O.O.M.
 */
export const useCreateReport = <TError = ErrorType<UnauthorizedResponse | ValidationErrorResponse | FirebaseUnavailableResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createReport>>, TError,{data: BodyType<ReportRequest>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createReport>>,
        TError,
        {data: BodyType<ReportRequest>},
        TContext
      > => {
      return useMutation(getCreateReportMutationOptions(options));
    }

